@SubscribeEvent
	public static void onRenderWorldLastEvent(RenderWorldLastEvent event){
		// Only render in first person
		if(Minecraft.getMinecraft().gameSettings.thirdPersonView == 0){

			EntityPlayer player = Minecraft.getMinecraft().player;

			if(EntityUtils.isCasting(player, Spells.shadow_ward)){

				GlStateManager.pushMatrix();

				GlStateManager.enableBlend();
				GlStateManager.blendFunc(GL11.GL_SRC_ALPHA, GL11.GL_ONE_MINUS_SRC_ALPHA);
				//GlStateManager.shadeModel(GL11.GL_SMOOTH);
				GlStateManager.disableLighting();
				//GlStateManager.disableAlpha();
				OpenGlHelper.setLightmapTextureCoords(OpenGlHelper.lightmapTexUnit, 240f, 240f);

				GlStateManager.translate(0, 1.2, 0);
				GlStateManager.rotate(-player.rotationYaw, 0, 1, 0);
				GlStateManager.rotate(player.rotationPitch, 1, 0, 0);

				Minecraft.getMinecraft().renderEngine.bindTexture(TEXTURE);

				GlStateManager.pushMatrix();

				GlStateManager.translate(0, 0, 1.2);
				GlStateManager.rotate(player.ticksExisted * -2, 0, 0, 1);
				GlStateManager.scale(1.1, 1.1, 1.1);

				Tessellator tessellator = Tessellator.getInstance();
				BufferBuilder buffer = tessellator.getBuffer();

				buffer.begin(GL11.GL_QUADS, DefaultVertexFormats.POSITION_TEX);

				buffer.pos(-0.5, 0.5, -0.5).tex(0, 0).endVertex();
				buffer.pos(0.5, 0.5, -0.5).tex(1, 0).endVertex();
				buffer.pos(0.5, -0.5, -0.5).tex(1, 1).endVertex();
				buffer.pos(-0.5, -0.5, -0.5).tex(0, 1).endVertex();

				tessellator.draw();

				buffer.begin(GL11.GL_QUADS, DefaultVertexFormats.POSITION_TEX);

				buffer.pos(-0.5, 0.5, -0.5).tex(0, 0).endVertex();
				buffer.pos(-0.5, -0.5, -0.5).tex(0, 1).endVertex();
				buffer.pos(0.5, -0.5, -0.5).tex(1, 1).endVertex();
				buffer.pos(0.5, 0.5, -0.5).tex(1, 0).endVertex();

				tessellator.draw();

				GlStateManager.popMatrix();

				//GlStateManager.shadeModel(GL11.GL_FLAT);
				GlStateManager.enableLighting();
				GlStateManager.disableBlend();

				GlStateManager.popMatrix();

			}
		}
	}

private void renderEntityModel(T entity, float limbSwing, float limbSwingAmount, float partialTicks,
			float ageInTicks, float netHeadYaw, float headPitch, float scale){

		GlStateManager.pushMatrix();
		// Enables texture tiling (Also used for guardian beam, beacon beam and ender crystal beam, amongst others)
		GlStateManager.glTexParameteri(GL11.GL_TEXTURE_2D, GL11.GL_TEXTURE_WRAP_S, GL11.GL_REPEAT);
		GlStateManager.glTexParameteri(GL11.GL_TEXTURE_2D, GL11.GL_TEXTURE_WRAP_T, GL11.GL_REPEAT);

		GlStateManager.depthMask(true); // Some entities set depth mask to false (i.e. no sorting of faces by depth)
		// In particular, LayerSpiderEyes sets it to false when the spider is invisible, for some reason.

		// Changes the scale at which the texture is applied to the model. See LayerCreeper for a similar example,
		// but with translation instead of scaling.
		// You can do all sorts of fun stuff with this, just by applying transformations in the 2D texture space.
		GlStateManager.matrixMode(GL11.GL_TEXTURE); // Switch to the 2D texture space
		GlStateManager.loadIdentity();

		ModelBase model = getModel(entity, partialTicks);

		// Calculate the scaling required in each direction
		double scaleX = 1, scaleY = 1;
		// It's more logical to use the model's texture size, but some classes don't bother setting it properly
		// (e.g. ModelVillager), so to get the correct dimensions I'm getting them from the first box instead.
		if(model.boxList != null && model.boxList.size() >= 1 && model.boxList.get(0) != null){
			scaleX = (double)model.boxList.get(0).textureWidth / textureWidth;
			scaleY = (double)model.boxList.get(0).textureHeight / textureHeight;
		}else{ // Fallback to model fields; should never be needed
			scaleX = (double)model.textureWidth / textureWidth;
			scaleY = (double)model.textureHeight / textureHeight;
		}

		GlStateManager.scale(scaleX, scaleY, 1);

		applyTextureSpaceTransformations(entity, partialTicks);

		GlStateManager.matrixMode(GL11.GL_MODELVIEW); // Switch back to the 3D model space

		boolean headWearHidden = false;
		boolean bodyWearHidden = false;
		boolean leftArmWearHidden = false;
		boolean rightArmWearHidden = false;
		boolean leftLegWearHidden = false;
		boolean rightLegWearHidden = false;

		if(!renderSecondLayer(entity, partialTicks)){
			// Hide the hat layer for bipeds, and all the other body part overlays for players
			if(model instanceof ModelBiped){
				headWearHidden = ((ModelBiped)model).bipedHeadwear.isHidden;
				((ModelBiped)model).bipedHeadwear.isHidden = true;
			}

			if(model instanceof ModelPlayer){
				bodyWearHidden = ((ModelPlayer)model).bipedBodyWear.isHidden;
				leftArmWearHidden = ((ModelPlayer)model).bipedLeftArmwear.isHidden;
				rightArmWearHidden = ((ModelPlayer)model).bipedRightArmwear.isHidden;
				leftLegWearHidden = ((ModelPlayer)model).bipedLeftLegwear.isHidden;
				rightLegWearHidden = ((ModelPlayer)model).bipedRightLegwear.isHidden;
				((ModelPlayer)model).bipedBodyWear.isHidden = true;
				((ModelPlayer)model).bipedLeftArmwear.isHidden = true;
				((ModelPlayer)model).bipedRightArmwear.isHidden = true;
				((ModelPlayer)model).bipedLeftLegwear.isHidden = true;
				((ModelPlayer)model).bipedRightLegwear.isHidden = true;
			}
		}

		// Actually render the model
		model.setLivingAnimations(entity, limbSwing, limbSwingAmount, partialTicks);
		model.render(entity, limbSwing, limbSwingAmount, ageInTicks, netHeadYaw, headPitch, scale);

		if(!renderSecondLayer(entity, partialTicks)){
			// Reset the hidden status of everything to how it was before
			if(model instanceof ModelBiped){
				((ModelBiped)model).bipedHeadwear.isHidden = headWearHidden;
			}

			if(model instanceof ModelPlayer){
				((ModelPlayer)model).bipedBodyWear.isHidden = bodyWearHidden;
				((ModelPlayer)model).bipedLeftArmwear.isHidden = leftArmWearHidden;
				((ModelPlayer)model).bipedRightArmwear.isHidden = rightArmWearHidden;
				((ModelPlayer)model).bipedLeftLegwear.isHidden = leftLegWearHidden;
				((ModelPlayer)model).bipedRightLegwear.isHidden = rightLegWearHidden;
			}
		}

		// Undo the texture scaling
		GlStateManager.matrixMode(GL11.GL_TEXTURE);
		GlStateManager.loadIdentity();
		GlStateManager.matrixMode(GL11.GL_MODELVIEW);

		GlStateManager.popMatrix();
	}

@Override
	public void render(@NotNull BabylonWeaponEntity weapon, float yaw, float partialTicks, PoseStack ms, MultiBufferSource buffers, int light) {
		ms.pushPose();
		ms.mulPose(VecHelper.rotateY(weapon.getRotation()));

		int live = weapon.getLiveTicks();
		int delay = weapon.getDelay();
		float charge = Math.min(10F, Math.max(live, weapon.getChargeTicks()) + partialTicks);
		float chargeMul = charge / 10F;

		ms.pushPose();
		ms.translate(-0.75, 0, 1); // X shifts the weapon hilt to the center of the circle, Z makes it intersect it.
		float s = 1.5F;
		ms.scale(s, s, s);
		ms.mulPose(VecHelper.rotateY(90F)); // Rotate to make it match facing, instead of perpendicular to the circle
		ms.mulPose(VecHelper.rotateZ(-45F)); // Perpendicular to the ground, instead of the rising 45 deg of the sprite

		BakedModel model = MiscellaneousModels.INSTANCE.kingKeyWeaponModels[weapon.getVariety()];
		Minecraft.getInstance().getBlockRenderer().getModelRenderer().renderModel(ms.last(), buffers.getBuffer(Sheets.translucentItemSheet()), null, model, 1, 1, 1, 0xF000F0, OverlayTexture.NO_OVERLAY);
		ms.popPose();

		Random rand = new Random(weapon.getUUID().getMostSignificantBits());
		ms.mulPose(VecHelper.rotateX(-90F)); // Lay the circle horizontally
		ms.translate(0F, -0.3F + rand.nextFloat() * 0.1F, 0F); // Randomly offset how deep the item is in the circle

		s = chargeMul;
		if (live > delay) {
			s -= Math.min(1F, (live - delay + partialTicks) * 0.2F);
		}
		s *= 2F;
		ms.scale(s, s, s);

		ms.mulPose(VecHelper.rotateY(charge * 9F + (weapon.tickCount + partialTicks) * 0.5F + rand.nextFloat() * 360F));

		VertexConsumer buffer = buffers.getBuffer(RenderHelper.BABYLON_ICON);
		Matrix4f mat = ms.last().pose();
		buffer.vertex(mat, -1, 0, -1).color(1, 1, 1, chargeMul).uv(0, 0).endVertex();
		buffer.vertex(mat, -1, 0, 1).color(1, 1, 1, chargeMul).uv(0, 1).endVertex();
		buffer.vertex(mat, 1, 0, 1).color(1, 1, 1, chargeMul).uv(1, 1).endVertex();
		buffer.vertex(mat, 1, 0, -1).color(1, 1, 1, chargeMul).uv(1, 0).endVertex();

		ms.popPose();
	}

private static RenderPhase.Texturing itemGlowTexturing(Color color) {
        return new RenderPhase.Texturing("spell_engine_item_glow_texturing",
                () -> {
                    // `getShaderColor` hands out the live array, not a copy of it
                    System.arraycopy(RenderSystem.getShaderColor(), 0, shaderColorToRestore, 0, 4);
                    glintAlphaToRestore = RenderSystem.getShaderGlintAlpha();

                    RenderSystem.setTextureMatrix(itemGlowTextureMatrix());

                    // Opacity is folded into the color instead of the alpha, because the additive blend
                    // scales by color, and the glint shader discards fragments below `alpha < 0.1`,
                    // which would cut faint glows off entirely instead of fading them out.
                    var intensity = color.alpha() * itemGlowGain;
                    RenderSystem.setShaderColor(
                            color.red() * intensity,
                            color.green() * intensity,
                            color.blue() * intensity,
                            1F);

                    // The glint shader fades by this, and it follows the `Glint Strength` video setting.
                    // This glow carries gameplay meaning, so it must not be dimmed away by a cosmetic option.
                    RenderSystem.setShaderGlintAlpha(1F);
                },
                () -> {
                    RenderSystem.resetTextureMatrix();
                    RenderSystem.setShaderColor(
                            shaderColorToRestore[0], shaderColorToRestore[1],
                            shaderColorToRestore[2], shaderColorToRestore[3]);
                    RenderSystem.setShaderGlintAlpha(glintAlphaToRestore);
                });
    }

@Override
    public void renderEffect(long appliedAtWorldTime, int amplifier, LivingEntity livingEntity, float delta, MatrixStack matrixStack,
                 VertexConsumerProvider vertexConsumers, int light) {
        var itemRenderer = MinecraftClient.getInstance().getItemRenderer();
        // World time, not Entity.age: the server stamps `appliedAtWorldTime` in its clock, and the
        // client's World.getTime() tracks it (shared origin, re-synced each second). Entity.age counts
        // from whenever each side first saw the entity, so `age - appliedAtAge` could start deeply
        // negative and skip the whole animation for seconds. See Synchronized.Effect.
        float rawTime = (livingEntity.getWorld().getTime() - appliedAtWorldTime) + delta;

        if (followYaw) {
            float yaw = livingEntity.getYaw(delta);
            matrixStack.multiply(RotationAxis.NEGATIVE_Y.rotationDegrees(yaw));
        }

        if (entityScaling != null) {
            float s = entityScaling.scaleFor(livingEntity);
            matrixStack.scale(s, s, s);
        }

        for (var effect : effects) {
            if (effect.model_id == null || effect.model_id.isEmpty()) continue;

            float age;
            if (playback == Playback.LOOP && effect.duration > 0) {
                age = rawTime % effect.duration;
            } else {
                age = rawTime;
            }

            ModelEffectOperations.renderEffect(effect, age, matrixStack, itemRenderer, vertexConsumers, light, livingEntity.getId());
        }
    }

public static boolean renderComposite(float scale, EntityRenderDispatcher dispatcher, ItemRenderer itemRenderer,
                                          Spell.ProjectileModelComposite composite, @Nullable String heldItemModelId,
                                          @Nullable Vec3d previousVelocity, Entity entity, float tickDelta, boolean allowSpin,
                                          MatrixStack matrices, VertexConsumerProvider vertexConsumers, int light) {
        // Skip while very fresh and very close to the camera, so a just-spawned projectile doesn't
        // fill the caster's view.
        if (entity.age < 2 && dispatcher.camera.getFocusedEntity().squaredDistanceTo(entity) < 12.25) {
            return false;
        }

        float age = entity.age + tickDelta;
        for (var model : composite.models) {
            var fx = model.fx;
            matrices.push();

            // Placement within the entity bounding box (entity space, before the entity scale).
            if (fx.positioning != null && fx.positioning.vertical != 0) {
                matrices.translate(0, fx.positioning.vertical * entity.getHeight(), 0);
            }
            // Overall projectile scale.
            matrices.scale(scale, scale, scale);
            // Facing relative to travel.
            applyCompositeOrientation(model.orientation, dispatcher, entity, previousVelocity, tickDelta, matrices);
            // Continuous spin (disabled e.g. while an arrow is stuck in the ground).
            if (allowSpin && (model.rotate_degrees_per_tick != 0 || model.rotate_degrees_offset != 0)) {
                matrices.multiply(RotationAxis.POSITIVE_Z.rotationDegrees(
                        model.rotate_degrees_offset + age * model.rotate_degrees_per_tick));
            }
            // modelFX animation (initial + animated transforms + fx.scale).
            ModelEffectOperations.applyTransforms(matrices, fx, age);

            var layer = SpellModelHelper.LAYERS.get(fx.light_emission);
            if (model.use_held_item) {
                // Held items MUST resolve through the item model path (itemRenderer.getModel(stack, ...)).
                // Resolving them as a raw model Identifier via CustomModels.render breaks on NeoForge: getModel returns the missing-model placeholder
                // (never null) for a bare item id — an item's model isn't registered under the `#standalone`
                // variant the NeoForge branch looks up — so the item-stack fallback never fires and an
                // empty/placeholder model is drawn. heldItemModelId is null for non-held projectiles (e.g.
                // arrows via ProjectileEntityRendererMixin), which then correctly skip these models.
                if (heldItemModelId != null && !heldItemModelId.isEmpty()) {
                    var stack = Registries.ITEM.get(Identifier.of(heldItemModelId)).getDefaultStack();
                    if (!stack.isEmpty()) {
                        var itemModel = itemRenderer.getModel(stack, entity.getWorld(), null, entity.getId());
                        // Item models are authored in item-display space; FIXED (item-frame) gives them the
                        // base orientation the projectile orientation math (e.g. ALONG_MOTION) expects.
                        itemModel.getTransformation().getTransformation(ModelTransformationMode.FIXED).apply(false, matrices);
                        CustomModels.renderModel(layer, (ItemRendererAccessor) itemRenderer, matrices, vertexConsumers, light, itemModel);
                    }
                }
            } else if (fx.model_id != null && !fx.model_id.isEmpty()) {
                // Custom (non-item) fx models render raw, with no display transform.
                CustomModels.render(layer, itemRenderer, Identifier.of(fx.model_id), null, matrices, vertexConsumers, light, entity.getId());
            }

            matrices.pop();
        }
        return true;
    }

private static void applyCompositeOrientation(Spell.ProjectileModelComposite.Orientation orientation, EntityRenderDispatcher dispatcher,
                                                  Entity entity, @Nullable Vec3d previousVelocity, float tickDelta, MatrixStack matrices) {
        switch (orientation) {
            case TOWARDS_CAMERA -> {
                matrices.multiply(dispatcher.getRotation());
                matrices.multiply(RotationAxis.POSITIVE_Y.rotationDegrees(180.0F));
            }
            case TOWARDS_MOTION, ALONG_MOTION -> {
                var velocity = entity.getVelocity();
                if (previousVelocity != null) {
                    velocity = previousVelocity.lerp(velocity, tickDelta);
                }
                velocity = velocity.normalize();
                var directionBasedYaw = Math.toDegrees(Math.atan2(velocity.x, velocity.z)) + 180F;
                var directionBasedPitch = Math.toDegrees(Math.asin(velocity.y));
                matrices.multiply(RotationAxis.POSITIVE_Y.rotationDegrees((float) directionBasedYaw));
                matrices.multiply(RotationAxis.POSITIVE_X.rotationDegrees((float) directionBasedPitch));
                if (orientation == Spell.ProjectileModelComposite.Orientation.ALONG_MOTION) {
                    // ALONG_MOTION models lie along their local X axis, so folding the +90 into the
                    // yaw would leave the pitch (applied around X) rotating the model about its own
                    // length — no elevation, model stuck facing the horizon. Instead convert the X
                    // length into the +Z "forward" that the yaw/pitch above already orient, applied
                    // innermost (last) so it doesn't cancel the vertical component of the motion.
                    matrices.multiply(RotationAxis.POSITIVE_Y.rotationDegrees(90F));
                }
            }
        }
    }
